// Construir prompt contextual
const message = $json.message;
const context = $json.context;
const intent = $json.intent;
const kbContext = $json.kbContext;

// Construir histórico formatado
const historyText = context.conversation.history
  .slice(-8)
  .map(h => `${h.role === 'assistant' ? 'Assistente' : 'Cliente'}: ${h.content}`)
  .join('\n\n');

// Construir contexto de KB se disponível
let kbText = '';
if (kbContext && kbContext.length > 0) {
  kbText = '\n\nInformações relevantes da base de conhecimento:\n' +
    kbContext.map(kb => `- ${kb.title}: ${kb.body.substring(0, 200)}...`).join('\n');
}

// Prompt baseado na intenção
const intentPrompts = {
  'INFO_GERAL': 'Forneça informações claras e úteis sobre nossos produtos/serviços.',
  'SUPORTE_TECNICO': 'Ajude o cliente a resolver o problema técnico de forma passo a passo.',
  'PEDIDO_STATUS': 'Forneça informações precisas sobre o status do pedido quando disponível.',
  'RETENÇÃO': 'Seja empático e tente ajudar o cliente, mas não insista se ele realmente quiser cancelar.',
  'ESCALACAO': 'Informe que está escalando para um agente humano.',
  'OUTRO': 'Responda de forma útil e amigável.'
};

const intentPrompt = intentPrompts[intent] || intentPrompts['OUTRO'];

const systemPrompt = `Você é um assistente virtual de atendimento ao cliente especializado, amigável e profissional.

Regras importantes:
- Seja sempre cordial, profissional e empático
- Use linguagem natural e conversacional
- Mantenha respostas concisas mas completas
- Se não souber algo, seja honesto
- Mantenha o contexto da conversa anterior
- ${intentPrompt}

Canal: ${context.ticket.channel}
Cliente: ${context.requester.name}`;

const userPrompt = `Histórico da conversa:
${historyText}

${kbText}

Mensagem atual do cliente:
${message}

Responda de forma natural e útil.`;

return {
  json: {
    systemPrompt,
    userPrompt,
    message,
    context,
    intent,
    kbContext
  }
};

// Processar resposta gerada
const aiResponse = $('IA: Gerar Resposta').item.json.choices[0].message.content;
const context = $('Construir Prompt').item.json.context;
const intent = $('Construir Prompt').item.json.intent;

// Limpar resposta
let cleanedResponse = aiResponse.trim();

// Remover prefixos comuns da IA
const prefixes = ['Assistente:', 'Bot:', 'IA:', 'Resposta:'];
for (const prefix of prefixes) {
  if (cleanedResponse.startsWith(prefix)) {
    cleanedResponse = cleanedResponse.substring(prefix.length).trim();
  }
}

return {
  json: {
    response: cleanedResponse,
    rawResponse: aiResponse,
    intent: intent,
    context: context,
    generatedAt: new Date().toISOString(),
    model: $env.OPENAI_MODEL || 'gpt-4'
  }
};
